import java.util.ArrayList;
import java.util.List;

public class StringSearchTour {
    static long comparisons;

    static List<Integer> naive(String text, String pattern) {
        List<Integer> hits = new ArrayList<>();
        for (int i = 0; i + pattern.length() <= text.length(); i++) {
            int j = 0;
            while (j < pattern.length()) {
                comparisons++;
                if (text.charAt(i + j) != pattern.charAt(j)) break;
                j++;
            }
            if (j == pattern.length()) hits.add(i);
        }
        return hits;
    }

    static List<Integer> kmp(String text, String pattern) {
        int m = pattern.length();
        int[] lps = new int[m];                       // longest proper prefix that is also a suffix
        for (int i = 1, len = 0; i < m; ) {
            if (pattern.charAt(i) == pattern.charAt(len)) lps[i++] = ++len;
            else if (len > 0) len = lps[len - 1];
            else lps[i++] = 0;
        }
        List<Integer> hits = new ArrayList<>();
        for (int i = 0, j = 0; i < text.length(); ) {
            comparisons++;
            if (text.charAt(i) == pattern.charAt(j)) {
                i++;
                j++;
                if (j == m) { hits.add(i - m); j = lps[j - 1]; }
            } else if (j > 0) j = lps[j - 1];         // reuse what already matched; i never moves back
            else i++;
        }
        return hits;
    }

    public static void main(String[] args) {
        String text = "a".repeat(40) + "b" + "a".repeat(20) + "b";
        String pattern = "aaaaab";
        comparisons = 0;
        List<Integer> a = naive(text, pattern);
        long naiveCount = comparisons;
        comparisons = 0;
        List<Integer> b = kmp(text, pattern);
        System.out.println("text: 40 a's, b, 20 a's, b (" + text.length() + " chars); pattern " + pattern);
        System.out.println("naive: matches at " + a + " using " + naiveCount + " character comparisons");
        System.out.println("KMP:   matches at " + b + " using " + comparisons + " character comparisons");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class Kmp {
    static int[] buildLps(String p) {
        int[] lps = new int[p.length()];
        int len = 0, i = 1;
        while (i < p.length()) {
            if (p.charAt(i) == p.charAt(len)) {
                lps[i++] = ++len;                      // the border grows by one
            } else if (len > 0) {
                System.out.println("  lps: mismatch at i=" + i + ", fall back len " + len + " -> " + lps[len - 1]);
                len = lps[len - 1];                    // try the next shorter border
            } else {
                lps[i++] = 0;
            }
        }
        return lps;
    }

    static List<Integer> search(String text, String p, int[] lps) {
        List<Integer> hits = new ArrayList<>();
        int i = 0, j = 0;
        while (i < text.length()) {
            if (text.charAt(i) == p.charAt(j)) {
                i++;
                j++;
                if (j == p.length()) {
                    hits.add(i - j);
                    System.out.println("  match at " + (i - j) + ", continue with j = " + lps[j - 1]);
                    j = lps[j - 1];                    // allow overlapping matches
                }
            } else if (j > 0) {
                System.out.println("  mismatch at text[" + i + "] with j=" + j + ": j -> " + lps[j - 1] + " (i stays)");
                j = lps[j - 1];
            } else {
                i++;
            }
        }
        return hits;
    }

    public static void main(String[] args) {
        String pattern = "ABABCABAB";
        int[] lps = buildLps(pattern);
        System.out.println("lps(" + pattern + ") = " + Arrays.toString(lps));

        String text = "ABABDABABCABABCABAB";
        System.out.println("search in " + text + ":");
        System.out.println("found at " + search(text, pattern, lps));

        String overlap = "ABAB";
        System.out.println("search ABAB in ABABCABABABAB:");
        System.out.println("found at " + search("ABABCABABABAB", overlap, buildLps(overlap)));
    }
}

import java.util.ArrayList;
import java.util.List;

public class RabinKarp {
    static final long B = 256;

    static void search(String text, String p, long mod) {
        int n = text.length(), m = p.length();
        long high = 1;                                        // B^(m-1) mod M
        for (int i = 1; i < m; i++) high = high * B % mod;
        long hp = 0, hw = 0;
        for (int i = 0; i < m; i++) {
            hp = (hp * B + p.charAt(i)) % mod;
            hw = (hw * B + text.charAt(i)) % mod;
        }
        List<Integer> matches = new ArrayList<>(), spurious = new ArrayList<>();
        for (int i = 0; ; i++) {
            if (hw == hp) {                                   // hashes agree: verify the characters
                if (text.regionMatches(i, p, 0, m)) matches.add(i);
                else spurious.add(i);
            }
            if (i + m >= n) break;
            hw = (hw - text.charAt(i) * high % mod + mod) % mod;   // drop the leading character
            hw = (hw * B + text.charAt(i + m)) % mod;               // shift and add the new one
        }
        System.out.println("M = " + mod + ": matches at " + matches + ", spurious hits at " + spurious);
    }

    public static void main(String[] args) {
        String text = "the cat sat on the mat with the hat";
        String pattern = "the";
        System.out.println("search \"" + pattern + "\" in \"" + text + "\"");
        search(text, pattern, 1_000_000_007L);
        search(text, pattern, 13);
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class BoyerMoore {
    static int comparisons;

    static List<Integer> search(String text, String p, boolean trace) {
        int[] last = new int[128];
        Arrays.fill(last, -1);
        for (int i = 0; i < p.length(); i++) last[p.charAt(i)] = i;       // rightmost occurrence
        List<Integer> hits = new ArrayList<>();
        int s = 0, m = p.length();
        while (s + m <= text.length()) {
            int j = m - 1;
            while (j >= 0) {
                comparisons++;
                if (p.charAt(j) != text.charAt(s + j)) break;
                j--;                                                        // right to left
            }
            if (j < 0) {
                hits.add(s);
                if (trace) System.out.println("  s=" + s + ": full match");
                s += 1;
            } else {
                char bad = text.charAt(s + j);
                int shift = Math.max(1, j - last[bad]);
                if (trace) System.out.println("  s=" + s + ": mismatch on '" + bad + "' at j=" + j + ", shift " + shift);
                s += shift;
            }
        }
        return hits;
    }

    static int naiveComparisons(String text, String p) {
        int count = 0;
        for (int s = 0; s + p.length() <= text.length(); s++) {
            for (int j = 0; j < p.length(); j++) {
                count++;
                if (text.charAt(s + j) != p.charAt(j)) break;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        String text = "HERE IS A SIMPLE EXAMPLE OF A SEARCH";
        String pattern = "EXAMPLE";
        comparisons = 0;
        System.out.println("search " + pattern + " in \"" + text + "\":");
        List<Integer> hits = search(text, pattern, true);
        System.out.println("found at " + hits + " with " + comparisons + " comparisons; naive needs "
                + naiveComparisons(text, pattern));
    }
}

