def search(text, p, trace):
    global comparisons
    last = {c: i for i, c in enumerate(p)}  # rightmost occurrence (later indexes overwrite)
    hits, s, m = [], 0, len(p)
    while s + m <= len(text):
        j = m - 1
        while j >= 0:
            comparisons += 1
            if p[j] != text[s + j]:
                break
            j -= 1  # right to left
        if j < 0:
            hits.append(s)
            if trace:
                print(f"  s={s}: full match")
            s += 1
        else:
            bad = text[s + j]
            shift = max(1, j - last.get(bad, -1))
            if trace:
                print(f"  s={s}: mismatch on '{bad}' at j={j}, shift {shift}")
            s += shift
    return hits


def naive_comparisons(text, p):
    count = 0
    for s in range(len(text) - len(p) + 1):
        for j in range(len(p)):
            count += 1
            if text[s + j] != p[j]:
                break
    return count


