import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SuffixArray {
    static String text;

    static int compareSuffix(int a, int b) {           // compare suffixes in place, no copies
        int n = text.length();
        while (a < n && b < n) {
            if (text.charAt(a) != text.charAt(b)) return text.charAt(a) - text.charAt(b);
            a++;
            b++;
        }
        return (n - a) - (n - b);                       // the shorter suffix comes first
    }

    // compare the suffix at i with the pattern, looking only at its first p.length() characters
    static int comparePrefix(int i, String p) {
        for (int k = 0; k < p.length(); k++) {
            if (i + k >= text.length()) return -1;
            if (text.charAt(i + k) != p.charAt(k)) return text.charAt(i + k) - p.charAt(k);
        }
        return 0;
    }

    public static void main(String[] args) {
        for (String t : new String[]{"banana", "mississippi"}) {
            text = t;
            int n = t.length();
            Integer[] sa = new Integer[n];
            for (int i = 0; i < n; i++) sa[i] = i;
            Arrays.sort(sa, SuffixArray::compareSuffix);
            System.out.println("suffix array of " + t + ": " + Arrays.toString(sa));
            if (t.equals("banana")) {
                for (int r = 0; r < n; r++) {
                    int lcp = 0;
                    if (r > 0) while (sa[r] + lcp < n && sa[r - 1] + lcp < n && t.charAt(sa[r] + lcp) == t.charAt(sa[r - 1] + lcp)) lcp++;
                    System.out.printf("  %d %-7s lcp=%d%n", sa[r], t.substring(sa[r]), lcp);
                }
            }
            String p = t.equals("banana") ? "ana" : "ssi";
            int lo = 0, hi = n;                              // first suffix >= p
            while (lo < hi) { int mid = (lo + hi) / 2; if (comparePrefix(sa[mid], p) < 0) lo = mid + 1; else hi = mid; }
            int first = lo;
            hi = n;                                          // first suffix that is > p (does not start with it)
            while (lo < hi) { int mid = (lo + hi) / 2; if (comparePrefix(sa[mid], p) <= 0) lo = mid + 1; else hi = mid; }
            List<Integer> found = new ArrayList<>();
            for (int r = first; r < lo; r++) found.add(sa[r]);
            found.sort(null);
            List<Integer> scan = new ArrayList<>();
            for (int i = t.indexOf(p); i >= 0; i = t.indexOf(p, i + 1)) scan.add(i);
            System.out.println("  \"" + p + "\" occurs at " + found + " (suffix ranks " + first + ".." + (lo - 1) + "), scan agrees: " + found.equals(scan));
        }
    }
}

