def suffix_array(t):
    # Simple construction: sort the start positions by the suffix text (fine for short strings)
    return sorted(range(len(t)), key=lambda i: t[i:])


def lcp(t, a, b):
    k = 0
    while a + k < len(t) and b + k < len(t) and t[a + k] == t[b + k]:
        k += 1
    return k


def find_all(t, sa, p):
    m = len(p)
    lo, hi = 0, len(sa)  # first suffix >= p
    while lo < hi:
        mid = (lo + hi) // 2
        if t[sa[mid]:sa[mid] + m] < p:
            lo = mid + 1
        else:
            hi = mid
    first, hi = lo, len(sa)  # first suffix that is > p (does not start with it)
    while lo < hi:
        mid = (lo + hi) // 2
        if t[sa[mid]:sa[mid] + m] <= p:
            lo = mid + 1
        else:
            hi = mid
    return first, lo


for t in ["banana", "mississippi"]:
    sa = suffix_array(t)
    print(f"suffix array of {t}: {sa}")
    if t == "banana":
        for r, i in enumerate(sa):
            print(f"  {i} {t[i:]:<7} lcp={lcp(t, i, sa[r - 1]) if r > 0 else 0}")
    p = "ana" if t == "banana" else "ssi"
    first, end = find_all(t, sa, p)
    found = sorted(sa[first:end])
    scan = [i for i in range(len(t)) if t.startswith(p, i)]
    print(f'  "{p}" occurs at {found} (suffix ranks {first}..{end - 1}), scan agrees: {str(found == scan).lower()}')

