import java.util.HashSet;
import java.util.Set;

public class StringHashing {
    static final long B = 131, M = 1_000_000_007L;
    static String s;
    static long[] prefix, power;

    static void preprocess(String text) {
        s = text;
        int n = s.length();
        prefix = new long[n + 1];
        power = new long[n + 1];
        power[0] = 1;
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = (prefix[i] * B + s.charAt(i)) % M;
            power[i + 1] = power[i] * B % M;
        }
    }

    static long hash(int l, int r) {                      // hash of s[l..r) in O(1)
        long x = (prefix[r] - prefix[l] * power[r - l]) % M;
        return (x + M) % M;                               // Java's % can be negative
    }

    static boolean same(int a, int b, int len) { return hash(a, a + len) == hash(b, b + len); }

    static int repeatedStart(int len) {                   // start of a repeated substring of this length, or -1
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i + len <= s.length(); i++) if (!seen.add(hash(i, i + len))) return i;
        return -1;
    }

    public static void main(String[] args) {
        preprocess("abracadabra");
        System.out.println("hash(\"abra\" at 0) = " + hash(0, 4) + ", hash(\"abra\" at 7) = " + hash(7, 11));
        System.out.println("same(0, 7, 4)? " + same(0, 7, 4) + ", same(0, 5, 4)? " + same(0, 5, 4));
        for (int k = 1; k <= 4; k++) {
            Set<Long> distinct = new HashSet<>();
            for (int i = 0; i + k <= s.length(); i++) distinct.add(hash(i, i + k));
            System.out.println("distinct substrings of length " + k + ": " + distinct.size());
        }
        int lo = 0, hi = s.length() - 1;                  // binary search the longest repeated length
        while (lo < hi) {
            int mid = (lo + hi + 1) / 2;
            if (repeatedStart(mid) >= 0) lo = mid; else hi = mid - 1;
        }
        int start = repeatedStart(lo);
        System.out.println("longest repeated substring: \"" + s.substring(start, start + lo) + "\" (length " + lo + ")");
    }
}

